"""Sequential exercises 1304–1308, page 339 (PDF page 340), Atanasyan 2023."""
import argparse
import json
from math import sqrt
from polygon_similarity_intro import entry, rectangle, scaled
from trigonometric_signs import grade
from vector_scaling import BOOK, ROOT

OUT=ROOT/'geometry-course/textbook/data/similar-perimeters-areas.json'
RULE='Если k — коэффициент первой фигуры относительно второй, то P₁/P₂=k и S₁/S₂=k². Сравнивай величины в одних единицах.'
CAPTION='В моделях штрих обозначает вторую фигуру. Масштаб относится ко всем её длинам, независимо от наклона на рисунке.'


def card(n,part,task,proof,steps,scenes,checks,hint,accepted=(),prompt=None):
    item=entry(n,part,[339],task,proof,steps,scenes,checks,RULE,hint,CAPTION,refs=[131,132])
    return grade(item,accepted,hint,prompt) if accepted else item


def triangles(title,bc,ratio,angle=0):
    return scaled(title,{'A':(bc/5,bc*.55),'B':(0,0),'C':(bc,0)},ratio,ratio,angle)


def perimeter_ratio():
    return card(1304,None,'У подобных треугольников ABC и A₁B₁C₁ стороны BC и B₁C₁ равны 1,4 м и 56 см соответственно. Найди отношение периметра первого треугольника к периметру второго.',
        'Переведём длины в сантиметры: BC=140 см. Все пары соответствующих сторон имеют одинаковое отношение 140/56=5/2. Складывая по три стороны, получаем то же отношение периметров. Ответ в запрошенном порядке: 5:2, или 2,5.',
        [('Приведи длины к одной единице','На первом чертеже единицей модели служит дециметр, поэтому BC=14, а B′C′=5,6. Для расчёта можно перевести обе длины в сантиметры.','Сравнение 1,4 и 56 без перевода смешивает метры с сантиметрами.'),
         ('Найди отношение соответствующих сторон','Сколько сантиметров в 1,4 метра? Затем раздели полученное число на 56, сохрани порядок первого и второго треугольников.','В одном метре 100 сантиметров. В исходном условии первый треугольник крупнее, поэтому его отношение ко второму больше 1.'),
         ('Проверь на новой паре','В третьей схеме соответствующие стороны равны 12 и 4 дм. Найди отношение периметра большего треугольника к меньшему.','Для периметров коэффициент остаётся линейным. Его квадрат используется для площадей.')],
        [triangles('Исходная пара в дециметрах',14,.4),triangles('Тот же масштаб после поворота',14,.4,22),triangles('Новая пара BC=12, B′C′=4',12,1/3,-22)],
        [('Сколько сантиметров в 1,4 м?','140','1,4·100=140.'),('Каково отношение периметров для сторон 12 и 4?','3','12/4=3.')],
        'Переведи 1,4 м в 140 см. Деление первой длины на вторую задаёт то же отношение, что и деление периметров.',
        ['5:2','5/2','2,5','2.5'], 'Введи отношение P(ABC) к P(A₁B₁C₁) как дробь или число.')


def trapezoids(title,w,h,k):
    return scaled(title,{'M':(0,0),'N':(w,0),'P':(w+1,4),'Q':(w+1-h,4)},k,k)


def side_from_difference():
    return card(1305,None,'Периметры подобных четырёхугольников MNPQ и M₁N₁P₁Q₁ относятся как 3:5. У первого MN=7 см. У второго сторона P₁Q₁ на 5 см длиннее M₁N₁. Найди PQ.',
        'Все длины первой фигуры относятся к соответствующим длинам второй как 3:5. Значит, разность соответствующих длин тоже изменяется в 5/3 раза. Во второй фигуре разность P₁Q₁−M₁N₁ равна 5 см, в первой PQ−MN=5·3/5=3 см. Следовательно, PQ=7+3=10 см. Проверка длинным способом: M₁N₁=35/3, P₁Q₁=50/3, а (50/3)·(3/5)=10.',
        [('Подпиши разность у правильной фигуры','Исходные 5 см — разность двух сторон второй фигуры. При переходе к первой каждую длину, а значит и их разность, умножаем на 3/5.','Прибавление 5 к стороне 7 смешивает прирост большой фигуры со стороной малой.'),
         ('Найди разность в первой фигуре','Вычисли 5·3/5. Затем прибавь результат к известной MN=7.','Требуется сторона PQ первой фигуры. Пересчитанная разность ещё не является целой стороной.'),
         ('Повтори для другого масштаба','В новой модели длины второй фигуры вдвое больше. M′N′=10, P′Q′=16. Первая MN=5. Сколько составляет PQ?','Полученную большую сторону можно сразу разделить на 2. При расчёте через разность уменьши сначала 16−10.')],
        [trapezoids('Исходные четырёхугольники с отношением 3:5',7,10,5/3),trapezoids('Сравни основания и их разность',7,10,5/3),trapezoids('Новая пара с масштабом 2',5,8,2)],
        [('Чему равна разность PQ−MN в сантиметрах?','3','5·3/5=3.'),('Какова сторона PQ новой фигуры?','8','16/2=8.')],
        'Пять сантиметров относятся к большей фигуре. Уменьши эту разность в отношении 3:5 и только затем прибавь к MN.',
        ['10','10 см','10,0','10.0'],'Введи длину PQ первой фигуры в сантиметрах.')


def area_pair(title,first,second):
    return scaled(title,rectangle(sqrt(first),sqrt(first)),sqrt(second/first),sqrt(second/first))


def table():
    item=card(1306,None,'В таблице для двух подобных многоугольников k — коэффициент первого относительно второго. Заполни по одной клетке в каждом столбце: (1) S₁=27 см², S₂=3 см², k=?; (2) S₁=640 см², k=2, S₂=?; (3) S₂=54 дм², k=2/3, S₁=?; (4) S₁=24 см², S₂=6 мм², k=?; (5) S₂=4a² см², k=√a, S₁=? (a>0).',
        'Одна формула для всех столбцов: S₁=k²S₂. (1) k=√(27/3)=3. (2) S₂=640/2²=160 см². (3) S₁=(2/3)²·54=24 дм². (4) 24 см²=2400 мм², поэтому k=√(2400/6)=20. (5) k²=a, значит S₁=a·4a²=4a³ см². В ответе порядок столбцов сохраняется.',
        [('Выбери действие по неизвестной клетке','Если неизвестно S₁, умножай S₂ на k². Если неизвестно S₂, дели S₁ на k². Для неизвестного k извлеки положительный корень из S₁/S₂. Примени правила к первым трём столбцам.','Подставление линейного k вместо k² изменит ответы во втором и третьем столбцах.'),
         ('Проверь единицы в четвёртом столбце','Один квадрат со стороной 1 см содержит 10·10 квадратов со стороной 1 мм. Переведи 24 см² в мм² и только затем дели площади. Во второй модели виден отдельный третий столбец с k=2/3.','Множитель перевода квадратных единиц равен 100, не 10.'),
         ('Проверь букву на новом числе','Для пятого столбца возьми a=4. Тогда S₂=64 см², k=2. Найди S₁. Сравни результат с формулой 4a³.','Квадрат √a равен a. Показатель степени в 4a² увеличится на один, когда умножишь на a.')],
        [area_pair('Первый столбец: площади 27 и 3',27,3),area_pair('Третий столбец: площади 24 и 54',24,54),area_pair('Проверка пятого столбца при a=4',256,64)],
        [('Сколько мм² содержится в 24 см²?','2400','24·100=2400.'),('Какова S₁ при a=4 в пятом столбце?','256','2²·64=256.')],
        'Запиши S₁=k²S₂. В четвёртом столбце перед извлечением корня замени 24 см² на 2400 мм².',
        [f'3{sep}160{sep}24{sep}20{sep}{expr}' for sep in (';','; ', ', ') for expr in ('4a^3','4а^3','4a³','4а³','4*a^3','4*а^3')],
        'Введи пять пропущенных величин по порядку через точку с запятой, без единиц. Степень можно записать как a^3 или a³.')
    return item


def square(part):
    scenes=[scaled('Квадрат и подобная фигура',rectangle(4,4),.5,.5,20),scaled('Квадрат со стороной 6 и его копия',rectangle(6,6),.5,.5,-12),scaled('Повтор: a=9 и k=3',rectangle(9,9),1/3,1/3,12)]
    if part=='а':
        return card(1307,'а','Квадрат F со стороной a подобен многоугольнику F₁. Докажи, что многоугольник F₁ тоже квадрат.',
            'Из подобия следует, что у F₁ тоже четыре вершины и четыре прямых угла. Так как стороны исходного квадрата равны, соответствующие стороны F₁ после умножения на один и тот же положительный коэффициент тоже равны. Четырёхугольник с четырьмя прямыми углами и четырьмя равными сторонами — квадрат.',
            [('Сохрани углы','Пройди по четырём вершинам первого квадрата. Соответствующие углы второй фигуры равны углам первого.','Четыре прямых угла позволяют назвать фигуру прямоугольником. Для квадрата нужно ещё проверить стороны.'),
             ('Сохрани равенство сторон','Любые две исходные стороны имеют одинаковую длину a. Их изображения обе имеют длину a/k, где k сравнивает первый квадрат со вторым. Сколько прямых углов у образа?','Размер образа может меняться, а равенство между его четырьмя сторонами сохраняется.'),
             ('Применяй доказательство при повороте','В третьей модели a=9, k=3. Образ повернули. Найди его сторону и объясни, почему он всё равно квадрат.','Положение относительно края экрана не входит в определение квадрата.')],scenes,
            [('Сколько прямых углов у F₁?','4','Все четыре соответствующих угла по 90°.'),('Какова сторона второго квадрата при a=9, k=3?','3','9/3=3.')],
            'Проверь отдельно четыре угла и четыре стороны образа. Эти две проверки вместе дают определение квадрата.')
    return card(1307,'б','У квадрата F сторона равна a. Найди площадь подобного ему многоугольника F₁, если коэффициент подобия F относительно F₁ равен k.',
        'Для длин k=a/a₁, поэтому сторона второго квадрата a₁=a/k. Его площадь S₁=(a/k)²=a²/k². Проверка по отношению площадей даёт тот же результат: площадь первого квадрата a² в k² раза больше площади второго, если k>1. Формула действует и при 0<k<1.',
        [('Уточни направление k','У первой фигуры сторона a. У второй обозначь её a₁. Условие даёт a/a₁=k.','Если первый квадрат крупнее второго, число k больше 1 и a₁ должна быть меньше a.'),
         ('Проверь на второй модели','Пусть a=6, k=2. Найди сторону второго квадрата, а затем его площадь.','Деление 36 только на 2 вместо 2² уменьшило бы площадь недостаточно.'),
         ('Примени другую пару данных','Для третьего построения a=9, k=3. Вычисли площадь второй фигуры. После этого замени числа буквами и запиши общую формулу.','После вычисления стороны её следует возвести в квадрат.')],scenes,
        [('Чему равна сторона второго квадрата при a=6, k=2?','3','6/2=3.'),('Чему равна площадь второго квадрата при a=9, k=3?','9','(9/3)²=9.')],
        'Условие сравнивает F с F₁. Делим сторону первого на k и возводим весь результат в квадрат.',
        [f'{a}{u}/{k}{v}' for a in ('a','а') for k in ('k','к') for u in ('^2','²') for v in ('^2','²')]
        +[f'({a}/{k}){e}' for a in ('a','а') for k in ('k','к') for e in ('^2','²')], 'Введи площадь F₁ через a и k. Например, степень записывается как x^2.')


def side_from_area():
    return card(1308,None,'Площади двух подобных многоугольников равны 75 м² и 300 м². Сторона второго равна 9 м. Чему равна соответствующая сторона первого многоугольника?',
        'Отношение площадей первого и второго равно 75/300=1/4. Поэтому отношение соответствующих сторон равно положительному корню √(1/4)=1/2. Сторона первой фигуры равна 9/2=4,5 м. Для проверки удвой её: получишь сторону 9 м и увеличение площади в четыре раза.',
        [('Сравни площади в одном порядке','У первой фигуры площадь в четыре раза меньше. Найди отношение первой площади ко второй.','Отношение площадей 1/4 относится к двум измерениям сразу, его нельзя сразу применять к стороне.'),
         ('Извлеки положительный корень','Если все длины увеличить вдвое, площадь увеличится в 2·2=4 раза. В сколько раз сторона второй фигуры больше сходственной стороны первой?','Длина положительна. Отрицательный корень в геометрическом отношении не используется.'),
         ('Повтори с другими площадями','В третьей задаче площади 10 и 90 м², сторона большой фигуры 6 м. Найди соответствующую сторону малой.','Площади теперь различаются в 9 раз, а не в 4. Заново найди линейный коэффициент.')],
        [scaled('75 м² и 300 м²: сторона большой фигуры 9 м',rectangle(50/3,4.5),2,2),scaled('Соответствующие стороны при повороте',rectangle(50/3,4.5),2,2,14),scaled('Новая пара с площадями 10 и 90',rectangle(5,2),3,3)],
        [('Во сколько раз больше сторона второй фигуры в исходной задаче?','2','√(300/75)=2.'),('Какова малая сторона при площадях 10 и 90 и большой стороне 6?','2','√9=3, поэтому 6/3=2.')],
        'Найди квадратный корень из 75/300 и умножь на длину соответствующей стороны второй фигуры.',
        ['4,5','4.5','9/2','4,5 м','4.5 м'],'Введи длину стороны первого многоугольника в метрах.')


if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    rows=[perimeter_ratio(),side_from_difference(),table(),square('а'),square('б'),side_from_area()]
    raw=json.dumps({'bookId':BOOK,'lessons':rows},ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==raw
    else:OUT.write_text(raw)
